-- Synthetic credentials and receipt evidence only; no external provider call.
update public.organizations set status='active' where id='20000000-0000-4000-8000-000000000001';
insert into public.configuration_versions(organization_id,version,settings) values('20000000-0000-4000-8000-000000000001',2,'{"sender":"owner@example.invalid","notificationRecipient":"owner@example.invalid"}');
insert into private.google_accounts(organization_id,revision,encrypted_tokens,email,subject,scopes,calendar_id,health,gmail_test,test_key) values('20000000-0000-4000-8000-000000000001',1,'synthetic-old-ciphertext','owner@example.invalid','synthetic-subject',array['https://www.googleapis.com/auth/gmail.send'],'synthetic-business-calendar','reconnect_required','accepted','90000000-0000-4000-8000-000000000001');
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000001","session_id":"10000000-0000-4000-8000-000000000001"}',true);
select public.configure_mail_delivery('20000000-0000-4000-8000-000000000001',true,1,'90000000-0000-4000-8000-000000000001',2,'synthetic-google-mail-enable');
reset role;
create temporary table google_reconnect_input(body jsonb);
insert into google_reconnect_input values('{"revision":1,"ciphertext":"synthetic-renewed-ciphertext","email":"owner@example.invalid","subject":"synthetic-subject","scopes":["openid","https://www.googleapis.com/auth/userinfo.email","https://www.googleapis.com/auth/gmail.send","https://www.googleapis.com/auth/calendar.calendarlist.readonly","https://www.googleapis.com/auth/calendar.events.owned","https://www.googleapis.com/auth/calendar.freebusy","https://www.googleapis.com/auth/calendar.app.created"],"actor":"00000000-0000-4000-8000-000000000001","calendarId":"synthetic-business-calendar","calendarVerified":true}');
grant select on google_reconnect_input to service_role;
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
do $$declare b jsonb;r jsonb;begin
 select body into b from google_reconnect_input;
 begin perform public.google_store('20000000-0000-4000-8000-000000000001','reconnect',b||'{"subject":"another-account"}');raise exception 'TEST FAILED account switch';exception when raise_exception then if sqlerrm<>'GOOGLE_ACCOUNT_MISMATCH' then raise;end if;end;
 begin perform public.google_store('20000000-0000-4000-8000-000000000001','reconnect',b||'{"calendarVerified":false}');raise exception 'TEST FAILED unverified calendar';exception when raise_exception then if sqlerrm<>'CALENDAR_RECONNECT_REVIEW_REQUIRED' then raise;end if;end;
 begin perform public.google_store('20000000-0000-4000-8000-000000000001','reconnect',b||'{"scopes":[]}');raise exception 'TEST FAILED incomplete scopes';exception when raise_exception then if sqlerrm<>'MISSING_GOOGLE_SCOPES' then raise;end if;end;
 begin perform public.google_store('20000000-0000-4000-8000-000000000001','reconnect',b||'{"actor":"00000000-0000-4000-8000-000000000002"}');raise exception 'TEST FAILED other tenant actor';exception when insufficient_privilege then null;end;
 perform pg_temp.assert_true(public.google_store('20000000-0000-4000-8000-000000000001','read','{}')->>'encrypted_tokens'='synthetic-old-ciphertext','failed consent leaves old connection intact');
 r:=public.google_store('20000000-0000-4000-8000-000000000001','reconnect',b);
 perform pg_temp.assert_true(r->>'calendar_id'='synthetic-business-calendar' and r->>'gmail_test'='accepted' and r->>'test_key'='90000000-0000-4000-8000-000000000001','single reconnect preserves calendar and receipt-confirmed mail');
 begin perform public.google_store('20000000-0000-4000-8000-000000000001','reconnect',b);raise exception 'TEST FAILED stale reconnect';exception when raise_exception then if sqlerrm<>'STALE_CONNECTION' then raise;end if;end;
 perform public.google_store('20000000-0000-4000-8000-000000000001','disconnect','{"revision":2,"actor":"00000000-0000-4000-8000-000000000001"}');
 r:=public.google_store('20000000-0000-4000-8000-000000000001','reconnect',b||'{"revision":3}');
 perform pg_temp.assert_true(r->>'calendar_id'='synthetic-business-calendar' and r->>'gmail_test'='accepted','explicit same-account reconnect can restore retained approval after lost credentials');
end$$;
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000001","session_id":"10000000-0000-4000-8000-000000000001"}',true);
select pg_temp.assert_true(public.mail_delivery_status('20000000-0000-4000-8000-000000000001')->>'enabled'='true','existing owner mail approval resumes');
select public.configure_mail_delivery('20000000-0000-4000-8000-000000000001',false,null,null,null,'synthetic-google-mail-pause');
reset role;
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select public.google_store('20000000-0000-4000-8000-000000000001','reconnect',(select body||'{"revision":4}' from google_reconnect_input));
reset role;
select pg_temp.assert_true(not (select enabled from private.mail_delivery_controls where organization_id='20000000-0000-4000-8000-000000000001'),'reconnect does not unpause owner-disabled sending');
select pg_temp.assert_true((select count(*)=0 from public.outbox),'reconnect sends no test or queued communication');
select pg_temp.assert_true((select count(*)=0 from private.google_calendar_creations),'reconnect creates no duplicate calendar');
rollback;
